function status = BigBandGraphs(numberbigbands,datafile)
%
%  Program for plotting the graphs associated with field bands 
%
%    Input:   (1) number of bands (numberbigbands)
%             (2) field data (in datafile): element-averaged quantity; one
%             value for each element in the entire mesh.
%             (3) .mat files with graph data generated by MechBands
%
%     Output: (1) bands determined using matlab graph utilities
%             (2) plots of band graphs labeled with mesh graph nodes and links
%


filebasename = input('Base name of mesh and mechband files: ', 's');

filecasename = input('Case name used in the result files: ', 's');


[meshfile,microstructurefile] = ReadNeperMshFile(filebasename);

phases = microstructurefile.phases;
grains = microstructurefile.grains;
rotations = microstructurefile.rotations;
orientations = microstructurefile.orientations;
ngrains=max(grains);
numnp   = size(meshfile.crd,2);
numel   = size(meshfile.con,2);
nnpe = 10;
nspe = 6;
nfpe = 4;
nps_local = [ 1 2 3 4 5 6; 1 6 5 9 10  7; 1 7 10 8 3 2; 3 8 10 9 5 4 ];

%construct graph object of the active links identified in MechBands

load([filebasename '_' filecasename '_statusfile.mat']);

  s = statusfile.connected_links(:,1);
  t = statusfile.connected_links(:,2); 
   
  graphfile = graph(s,t);
    
%determine sets of connected elements using  conncomp 
  
  [bins,binsizes] = conncomp(graphfile);
  
% bins hold the bin number for each node.    
% binsizes gives the number of nodes in each bin.  
  
  num_nodes = size(bins,2);
% Note that there are fewer nodes in the graph than there are elements in the mesh (meaning that
% some unconnected elements are unaccounted for.
  
  [bigbins,bigbins_inv] = sort(binsizes,'descend');
  
% bigbins gives the binsizes in descending order (will be used to identify the numberbigbands largest bands
% bigbins_inv gives the bin number associated with the ordered bin size 


% now give each element in the mesh a number corresponding to the band rank
% the rank is defined as numberbigbands for the largest and decreases from there
% this array is given to the vtk file and used as a thresholding parameter
% to plot onls elements within the largest connected sets of elements

element_bands = zeros(numel,1);
element_numbers = zeros(numel,1);

for iele = 1:1:numel
    element_numbers(iele) = iele;
end

for ibb = 1:1:numberbigbands
  bandcode = numberbigbands - ibb +1;
  ibb1 = bigbins_inv(ibb);
  ibb2 = bigbins(ibb);
    
  % create a list of nodes(elements) associated with the bin
  ibinsize = bigbins(ibb);
  binlist = zeros(ibinsize,1);
  ictr = 1;
  for jbb = 1:1:num_nodes
      if(bins(jbb)==ibb1)
          binlist(ictr) = jbb;
          ictr = ictr+1;
      end
  end
  
  for jbb = 1:1:ibb2
      elenumbb = binlist(jbb); 
      element_bands(elenumbb) = bandcode;
  end
    
end

%  Export vtk file for plotting   

graphdatafile = Data_Structure_Graph(element_bands,element_numbers,datafile);


SUF = 'vtk';

file_graphs_VTK = fopen(sprintf('%s.%s', [filebasename '_' filecasename '_graph'], SUF), 'w');

Export_Graph_VTK(file_graphs_VTK, graphdatafile, meshfile,  phases,grains);
  

% Now generate graphs of the larger bands based on the files generated by MechBands 

% labels of the nodes and links correspond to the mesh graph, not the band graph

for ibb = 1:1:numberbigbands

bandgraphname = [filebasename '_' filecasename '_bigband' num2str(ibb) '_graph.mat'];   
load(bandgraphname);
numnodes = size(bigbandgraphfile.graph_nodenames,2);
nodenumbers = zeros(1,numnodes);
elementnumberstring = string(bigbandgraphfile.graph_nodenames);
numlinks = size(bigbandgraphfile.band_global_link,2);
linknumbers = zeros(1,numlinks);
linknumberstring = string(bigbandgraphfile.band_global_link);
for inn = 1:1:numnodes
    nodenumbers(inn) = inn;
end
for iln = 1:1:numlinks
    linknumbers(iln) = iln;
end

% 
%     
   figure(ibb+10)
   clf;  

  s = bigbandgraphfile.graph_links_unique(:,1);
  t = bigbandgraphfile.graph_links_unique(:,2); 
  
  graphfile = graph(s,t);
  
  plot(graphfile,'NodeLabel',elementnumberstring,'EdgeLabel',linknumberstring);
   
end

     status = 'done with graph plots';
